const test = require("node:test");
const assert = require("node:assert");

const { EventBus } = require("./bus");

test("wildcard subscription catches namespaced events", () => {
  const bus = new EventBus();
  const seen = [];
  bus.on("user.*", (p) => seen.push(p));

  bus.emit("user.created", "a");
  bus.emit("user.deleted", "b");

  assert.deepStrictEqual(seen, ["a", "b"]);
});

test("wildcard does not match the bare prefix or an unrelated event sharing it", () => {
  const bus = new EventBus();
  const seen = [];
  bus.on("user.*", (p) => seen.push(p));

  bus.emit("user", "bare");                 // no dot after prefix - must NOT match
  bus.emit("userprofile.updated", "sneaky"); // shares the prefix string, different namespace
  bus.emit("order.created", "unrelated");

  assert.deepStrictEqual(seen, []);
});

test("exact and wildcard subscriptions on the same bus both fire", () => {
  const bus = new EventBus();
  const exact = [];
  const wild = [];
  bus.on("user.created", (p) => exact.push(p));
  bus.on("user.*", (p) => wild.push(p));

  bus.emit("user.created", "x");

  assert.deepStrictEqual(exact, ["x"]);
  assert.deepStrictEqual(wild, ["x"]);
});

reference_solution.bus.js:
class EventBus {
  constructor() {
    this.listeners = new Map(); // pattern (exact name, or "prefix.*") -> [handlers]
  }

  on(event, handler) {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    this.listeners.get(event).push(handler);
  }

  emit(event, payload) {
    for (const [pattern, handlers] of this.listeners) {
      if (matches(pattern, event)) {
        for (const h of handlers) {
          h(payload);
        }
      }
    }
  }
}

function matches(pattern, event) {
  if (pattern === event) {
    return true;
  }
  if (pattern.endsWith(".*")) {
    const prefix = pattern.slice(0, -1); // keep the trailing "."
    return event.startsWith(prefix) && event.length > prefix.length;
  }
  return false;
}

module.exports = { EventBus };

